from __future__ import annotations

__doc__ = """ctypes-based Python wrappers for generated CUDA libraries."""

import ctypes
from os import PathLike
from pathlib import Path

import numpy as np

from ...libroutinevar import (
    LibRoutineInputVariable,
    LibRoutineOutputVariable,
    LibRoutineInOutVariable,
)
from ..pywrapper_library import (
    PyWrapperLibraryBase,
    WrapperBase,
    _RequestValue,
)

try:
    import cupy as cp
except ImportError:
    cp = None

try:
    import pycuda.driver as cuda_driver
except ImportError:
    cuda_driver = None


class CUDAWrapper(WrapperBase):
    """Adapt wrapper arguments to a CUDA host-library ABI."""

    NP_DTYPE_LOOKUP = {
        "f64": np.float64,
        "f32": np.float32,
        "i64": np.int64,
        "i32": np.int32,
    }

    C_DTYPE_LOOKUP = {
        "f64": ctypes.c_double,
        "f32": ctypes.c_float,
        "i64": ctypes.c_int64,
        "i32": ctypes.c_int32,
    }

    def call(self, *args, **kwargs):
        self.prepare_inputs(args, kwargs)
        self.prepare_buffers()
        self.prepare_returns()
        self.prepare_inouts()
        for all_args in self.prepare_arguments_iter():
            call_args, _keepalive, needs_sync = self.prepare_cuda_call_arguments(
                all_args
            )
            self._exec(*call_args)
            if needs_sync:
                self.synchronize_device()
        return self.extract_from_returns()

    def adapt_call_arguments(self, all_args):
        call_args, keepalive, _needs_sync = self.prepare_cuda_call_arguments(
            all_args
        )
        return call_args, keepalive

    def prepare_cuda_call_arguments(self, all_args):
        converted = []
        keepalive = []
        needs_sync = False
        for value, spec in zip(all_args, self.argument_specs):
            arg_type, variable, _name, _key, _adaa = spec
            call_arg, refs, is_device_arg = self.convert_argument(
                value=value,
                variable=variable,
                arg_type=arg_type,
            )
            converted.append(call_arg)
            keepalive.extend(refs)
            needs_sync = needs_sync or is_device_arg
        return tuple(converted), keepalive, needs_sync

    def convert_argument(self, *, value, variable, arg_type):
        del arg_type
        if isinstance(value, _RequestValue):
            value = value.value

        np_dtype = type(self).NP_DTYPE_LOOKUP[variable.dtype]
        c_dtype = type(self).C_DTYPE_LOOKUP[variable.dtype]

        if variable.is_scalar:
            return self.convert_scalar_argument(
                value=value,
                variable=variable,
                np_dtype=np_dtype,
                c_dtype=c_dtype,
            )
        return self.convert_array_argument(
            value=value,
            variable=variable,
            np_dtype=np_dtype,
            c_dtype=c_dtype,
        )

    def convert_scalar_argument(self, *, value, variable, np_dtype, c_dtype):
        if isinstance(value, c_dtype):
            return value, [value], False

        if isinstance(variable, LibRoutineInputVariable):
            if hasattr(value, "__cuda_array_interface__") or hasattr(
                value, "gpudata"
            ):
                value = self.extract_scalar_from_device(value, np_dtype)
            elif isinstance(value, np.ndarray):
                value = np.asarray(value, dtype=np_dtype).reshape(-1)[0]
            elif hasattr(value, "item"):
                value = value.item()
            return c_dtype(value), [], False

        device_pointer = self.as_device_pointer(
            value=value,
            variable=variable,
            np_dtype=np_dtype,
            c_dtype=c_dtype,
            require_size=1,
            allow_input_copy=False,
        )
        if device_pointer is not None:
            return device_pointer[0], device_pointer[1], True

        if hasattr(value, "contents"):
            return value, [value], False

        if isinstance(value, np.ndarray):
            array = np.asarray(value, dtype=np_dtype)
            if array.size != 1:
                raise ValueError(
                    f"Scalar CUDA argument {variable.name} expects exactly one value."
                )
            if not array.flags["C_CONTIGUOUS"]:
                raise ValueError(
                    f"Scalar storage for {variable.name} must be C-contiguous."
                )
            ptr = array.ctypes.data_as(ctypes.POINTER(c_dtype))
            return ptr, [array, ptr], False

        holder = c_dtype(value.item() if hasattr(value, "item") else value)
        ptr = ctypes.pointer(holder)
        return ptr, [holder, ptr], False

    def convert_array_argument(self, *, value, variable, np_dtype, c_dtype):
        device_pointer = self.as_device_pointer(
            value=value,
            variable=variable,
            np_dtype=np_dtype,
            c_dtype=c_dtype,
            require_size=variable.size,
            allow_input_copy=isinstance(variable, LibRoutineInputVariable),
        )
        if device_pointer is not None:
            return device_pointer[0], device_pointer[1], True

        if isinstance(value, ctypes.Array):
            return value, [value], False

        array = np.asarray(value, dtype=np_dtype)
        if array.ndim != 1:
            raise ValueError(
                f"CUDA wrapper expects 1D storage for argument {variable.name}."
            )
        if variable.size is not None and len(array) != variable.size:
            raise ValueError(
                f"CUDA wrapper expects size {variable.size} for {variable.name}, "
                f"got {len(array)}."
            )
        if not array.flags["C_CONTIGUOUS"]:
            if isinstance(variable, LibRoutineInputVariable):
                array = np.ascontiguousarray(array, dtype=np_dtype)
            else:
                raise ValueError(
                    f"Output-capable argument {variable.name} must be contiguous."
                )
        ptr = array.ctypes.data_as(ctypes.POINTER(c_dtype))
        return ptr, [array, ptr], False

    def extract_scalar_from_device(self, value, np_dtype):
        if cp is not None and isinstance(value, cp.ndarray):
            array = cp.asarray(value, dtype=np_dtype).reshape(-1)
            if array.size != 1:
                raise ValueError("CUDA scalar device argument must have size 1.")
            return array.get()[0]
        interface = getattr(value, "__cuda_array_interface__", None)
        if interface is None:
            raise ValueError("Cannot extract scalar value from device object.")
        shape = interface.get("shape", ())
        if int(np.prod(shape, dtype=int)) != 1:
            raise ValueError("CUDA scalar device argument must have size 1.")
        raise ValueError(
            "Scalar device arguments require CuPy-backed storage at the moment."
        )

    def as_device_pointer(
        self,
        *,
        value,
        variable,
        np_dtype,
        c_dtype,
        require_size,
        allow_input_copy,
    ):
        metadata = self.get_device_array_metadata(value)
        if metadata is None:
            return None

        value_dtype = getattr(value, "dtype", None)
        if value_dtype is not None and np.dtype(value_dtype) != np.dtype(np_dtype):
            if allow_input_copy and cp is not None and isinstance(value, cp.ndarray):
                converted = cp.asarray(value, dtype=np_dtype)
                return self.as_device_pointer(
                    value=converted,
                    variable=variable,
                    np_dtype=np_dtype,
                    c_dtype=c_dtype,
                    require_size=require_size,
                    allow_input_copy=False,
                )
            raise ValueError(
                f"CUDA argument {variable.name} expects dtype "
                f"{np.dtype(np_dtype)}, got {np.dtype(value_dtype)}."
            )

        size = metadata["size"]
        if require_size is not None and size != require_size:
            raise ValueError(
                f"CUDA wrapper expects size {require_size} for {variable.name}, "
                f"got {size}."
            )

        strides = metadata["strides"]
        expected_stride = np.dtype(np_dtype).itemsize
        is_contiguous = strides in (None, (expected_stride,))
        if not is_contiguous:
            if allow_input_copy and cp is not None and isinstance(value, cp.ndarray):
                contiguous = cp.ascontiguousarray(value, dtype=np_dtype)
                return self.as_device_pointer(
                    value=contiguous,
                    variable=variable,
                    np_dtype=np_dtype,
                    c_dtype=c_dtype,
                    require_size=require_size,
                    allow_input_copy=False,
                )
            raise ValueError(
                f"CUDA argument {variable.name} must be contiguous device storage."
            )

        ptr = ctypes.cast(
            ctypes.c_void_p(int(metadata["pointer"])),
            ctypes.POINTER(c_dtype),
        )
        return ptr, [value, ptr]

    def get_device_array_metadata(self, value):
        interface = getattr(value, "__cuda_array_interface__", None)
        if interface is not None:
            shape = interface.get("shape", ())
            if len(shape) == 0:
                size = 1
            elif len(shape) == 1:
                size = int(shape[0])
            else:
                raise ValueError(
                    "CUDA wrapper currently expects flat 1D device arrays."
                )
            pointer = interface.get("data", (0, False))[0]
            if pointer in (None, 0):
                raise ValueError("CUDA argument exposes a null device pointer.")
            return {
                "pointer": pointer,
                "size": size,
                "strides": interface.get("strides"),
            }

        gpudata = getattr(value, "gpudata", None)
        if gpudata is not None:
            size = getattr(value, "size", None)
            shape = getattr(value, "shape", None)
            if shape is not None and len(shape) != 1:
                raise ValueError(
                    "CUDA wrapper currently expects flat 1D device arrays."
                )
            if size is None:
                raise ValueError("Cannot determine size of GPU device buffer.")
            strides = getattr(value, "strides", None)
            return {
                "pointer": int(gpudata),
                "size": int(size),
                "strides": strides,
            }

        return None

    def synchronize_device(self):
        if cp is not None:
            cp.cuda.runtime.deviceSynchronize()
            return
        if cuda_driver is not None:
            cuda_driver.Context.synchronize()


class CUDAKernelCallable:
    """Launch a compiled CUDA kernel directly through CuPy."""

    def __init__(self, raw_kernel, libroutine):
        self._raw_kernel = raw_kernel
        self._libroutine = libroutine
        self._grid = self._compute_dim3("block")
        self._block = self._compute_dim3("thread")

    def _compute_dim3(self, role):
        extents = {"x": 1, "y": 1, "z": 1}
        container = getattr(self._libroutine, "container", None)
        if container is None:
            return (1,)
        for variable in container.get_kernel_variables():
            if getattr(variable, "launch_role", None) != role:
                continue
            axis = getattr(variable, "launch_axis", "x")
            extents[axis] = max(extents[axis], int(variable.launch_extent))
        ordered = [extents["x"], extents["y"], extents["z"]]
        while len(ordered) > 1 and ordered[-1] == 1:
            ordered.pop()
        return tuple(ordered)

    def __call__(self, *kernel_args):
        self._raw_kernel(self._grid, self._block, kernel_args)


class CUDAKernelWrapper(WrapperBase):
    """Launch CUDA kernels directly from Python using CuPy."""

    NP_DTYPE_LOOKUP = CUDAWrapper.NP_DTYPE_LOOKUP

    def call(self, *args, **kwargs):
        self.prepare_inputs(args, kwargs)
        self.prepare_buffers()
        self.prepare_returns()
        self.prepare_inouts()
        for all_args in self.prepare_arguments_iter():
            kernel_args, needs_sync = self.prepare_kernel_arguments(all_args)
            self._exec(*kernel_args)
            if needs_sync:
                self.synchronize_device()
        return self.extract_from_returns()

    def prepare_kernel_arguments(self, all_args):
        converted = []
        needs_sync = False
        for value, spec in zip(all_args, self.argument_specs):
            arg_type, variable, _name, _key, _adaa = spec
            call_arg, is_device_arg = self.convert_argument(
                value=value,
                variable=variable,
                arg_type=arg_type,
            )
            converted.append(call_arg)
            needs_sync = needs_sync or is_device_arg
        return tuple(converted), needs_sync

    def adapt_call_arguments(self, all_args):
        kernel_args, _needs_sync = self.prepare_kernel_arguments(all_args)
        return kernel_args, []

    def convert_argument(self, *, value, variable, arg_type):
        del arg_type
        if isinstance(value, _RequestValue):
            value = value.value

        np_dtype = type(self).NP_DTYPE_LOOKUP[variable.dtype]
        if variable.is_scalar:
            return self.convert_scalar_argument(
                value=value,
                variable=variable,
                np_dtype=np_dtype,
            )
        return self.convert_array_argument(
            value=value,
            variable=variable,
            np_dtype=np_dtype,
        )

    def convert_scalar_argument(self, *, value, variable, np_dtype):
        if isinstance(value, np.ndarray):
            array = np.asarray(value, dtype=np_dtype).reshape(-1)
            if array.size != 1:
                raise ValueError(
                    f"Scalar CUDA kernel argument {variable.name} expects one value."
                )
            return array[0], False
        if cp is not None and isinstance(value, cp.ndarray):
            array = cp.asarray(value, dtype=np_dtype).reshape(-1)
            if array.size != 1:
                raise ValueError(
                    f"Scalar CUDA kernel argument {variable.name} expects one value."
                )
            return array[0].item(), True
        if hasattr(value, "item"):
            return value.item(), False
        return value, False

    def convert_array_argument(self, *, value, variable, np_dtype):
        if cp is not None and isinstance(value, cp.ndarray):
            array = cp.asarray(value, dtype=np_dtype)
            if array.ndim != 1:
                raise ValueError(
                    f"CUDA kernel wrapper expects flat storage for {variable.name}."
                )
            if variable.size is not None and int(array.size) != int(variable.size):
                raise ValueError(
                    f"CUDA kernel wrapper expects size {variable.size} "
                    f"for {variable.name}, got {array.size}."
                )
            if not array.flags.c_contiguous:
                if isinstance(variable, LibRoutineInputVariable):
                    array = cp.ascontiguousarray(array, dtype=np_dtype)
                else:
                    raise ValueError(
                        f"Output-capable kernel argument {variable.name} must be contiguous."
                    )
            return array, True

        if hasattr(value, "__cuda_array_interface__"):
            shape = value.__cuda_array_interface__.get("shape", ())
            if len(shape) != 1:
                raise ValueError(
                    f"CUDA kernel wrapper expects flat storage for {variable.name}."
                )
            return value, True

        if cp is None:
            raise RuntimeError(
                "Direct CUDA kernel calls require CuPy to manage the kernel module."
            )
        if isinstance(variable, LibRoutineInputVariable):
            array = cp.asarray(value, dtype=np_dtype).reshape(-1)
            if variable.size is not None and int(array.size) != int(variable.size):
                raise ValueError(
                    f"CUDA kernel wrapper expects size {variable.size} "
                    f"for {variable.name}, got {array.size}."
                )
            return array, True
        raise ValueError(
            f"Output-capable kernel argument {variable.name} must already be device storage."
        )

    def synchronize_device(self):
        if cp is not None:
            cp.cuda.runtime.deviceSynchronize()
            return
        if cuda_driver is not None:
            cuda_driver.Context.synchronize()


class CUDAPyWrapperLibrary(PyWrapperLibraryBase):
    """Python wrapper library for CUDA host libraries via `ctypes`."""

    WRAPPER_CLASS = CUDAWrapper

    C_DTYPE_LOOKUP = CUDAWrapper.C_DTYPE_LOOKUP

    def __init__(self, wrapped_library, wrapper_lib=None, build_hash=None):
        wrapper_lib = self._prepare_wrapper_lib(wrapped_library, wrapper_lib)
        super().__init__(
            wrapped_library,
            wrapper_lib=wrapper_lib,
            build_hash=build_hash,
        )
        self._kernel_module = None

    @classmethod
    def from_compiled_hash(
        cls,
        library_class,
        plain_name,
        build_hash,
        *,
        wrapper_lib=None,
        **library_kwargs,
    ):
        if wrapper_lib is None:
            preview_library = library_class(
                plain_name,
                build_hash=build_hash,
                **library_kwargs,
            )
            wrapper_lib = preview_library.sharedlibname
        return super().from_compiled_hash(
            library_class,
            plain_name,
            build_hash,
            wrapper_lib=wrapper_lib,
            **library_kwargs,
        )

    def _prepare_wrapper_lib(self, wrapped_library, wrapper_lib):
        if wrapper_lib is None:
            return None
        if isinstance(wrapper_lib, (str, PathLike)):
            wrapper_path = Path(wrapper_lib)
            if not wrapper_path.is_absolute():
                wrapper_lib = wrapped_library.relative_to_basepath(wrapper_lib)
            return ctypes.CDLL(str(wrapper_lib))
        return wrapper_lib

    def close(self):
        """Release CUDA-specific wrapper state before generic teardown."""
        self._kernel_module = None
        super().close()

    def _load_kernel_module(self):
        if cp is None:
            raise RuntimeError(
                "Direct CUDA kernel calls require CuPy and a compiled PTX module."
            )
        if self._kernel_module is not None:
            return self._kernel_module
        kernel_module_path = Path(
            self.wrapped_library.relative_to_basepath(
                self.wrapped_library.kernelmodulename
            )
        ).resolve()
        if not kernel_module_path.exists():
            raise FileNotFoundError(
                f"compiled CUDA kernel module not found at {kernel_module_path}"
            )
        self._kernel_module = cp.RawModule(path=str(kernel_module_path))
        return self._kernel_module

    def resolve_wrapper_callable(self, libroutine_name, libroutine):
        if libroutine.is_kernel:
            module = self._load_kernel_module()
            raw_kernel = module.get_function(libroutine_name)
            return CUDAKernelCallable(raw_kernel, libroutine)
        if self.wrapper_lib is None:
            raise ValueError("wrapper_lib must be set for CUDA wrapper libraries")
        routine = getattr(self.wrapper_lib, libroutine_name)
        self.configure_routine_signature(routine, libroutine)
        return routine

    def create_wrapper_instance(
        self,
        name,
        exe,
        arguments,
        libroutine,
        *,
        owner=None,
        owner_token=None,
        reuse_buffer=False,
    ):
        wrapper_class = (
            CUDAKernelWrapper if libroutine.is_kernel else type(self).WRAPPER_CLASS
        )
        return wrapper_class(
            name=name,
            exe=exe,
            arguments=arguments,
            libroutine=libroutine,
            owner=owner,
            owner_token=owner_token,
            reuse_buffer=reuse_buffer,
        )

    def configure_routine_signature(self, routine, libroutine):
        routine.restype = None
        routine.argtypes = [
            self.create_ctypes_argtype(arg)
            for arg in libroutine.get_arguments()
        ]

    def create_ctypes_argtype(self, arg):
        c_dtype = type(self).C_DTYPE_LOOKUP[arg.dtype]

        if arg.is_scalar:
            if isinstance(arg, LibRoutineInputVariable):
                return c_dtype
            if isinstance(
                arg, (LibRoutineOutputVariable, LibRoutineInOutVariable)
            ):
                return ctypes.POINTER(c_dtype)

        return ctypes.POINTER(c_dtype)
